/**
 * Utility to safely retrieve the first item from a specific node
 */
function getFirstItem(nodeName) {
  try {
    // We use node name directly; ensure these names match your canvas exactly
    const arr = $(nodeName).all();
    if (!arr || !Array.isArray(arr) || arr.length === 0) return null;
    return arr[0];
  } catch (e) {
    return null;
  }
}

/**
 * Utility to handle content that might be JSON or Plain Text
 */
function smartParse(rawContent, typeLabel) {
  if (!rawContent) return { type: "empty", content: `No ${typeLabel} was generated.` };

  if (typeof rawContent === 'object') return rawContent;

  try {
    // Remove markdown code fences if the LLM included them
    const cleanJson = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanJson);
  } catch (e) {
    // Fallback if the LLM output was just plain text/paragraphs
    return {
      type: "plain_text",
      title: typeLabel,
      content: rawContent.trim()
    };
  }
}

// 1. Extract raw outputs from the specific worker nodes
const summaryItem = getFirstItem('Summarizer Agent');
const quizItem = getFirstItem('Quiz Agent');
const flashItem = getFirstItem('Flashcard Agent');

// 2. Map the actual property (usually .output or .text for AI Agents)
const summaryRaw = summaryItem?.json?.output || summaryItem?.json?.text || null;
const quizRaw = quizItem?.json?.output || quizItem?.json?.text || null;
const flashRaw = flashItem?.json?.output || flashItem?.json?.text || null;

// 3. Process outputs using Smart Parse to ensure valid JSON objects
const summary = smartParse(summaryRaw, "Summary");
const quiz = smartParse(quizRaw, "Quiz");
const flashcards = smartParse(flashRaw, "Flashcards");

// 4. Return the consolidated object
return [
  {
    json: {
      status: "success",
      study_pack: {
        summary: summary,
        quiz: quiz,
        flashcards: flashcards
      },
      metadata: {
        generated_at: new Date().toISOString(),
        version: "2.0"
      },
    },
  },
];

